// 1. Base URL: f_TPR=r3600 (Last 1 hour) | f_JT=F,C (Full-Time AND Contract)
let url = "https://www.linkedin.com/jobs/search/?f_TPR=r3600&f_JT=F,C,I&sortBy=DD";

// 2. Fetch inputs from Google Sheets
const baseKeyword = $input.first().json.Keyword || "";
const location = $input.first().json.Location || "";
const experienceLevel = $input.first().json['Experience Level'] || "";
const remote = $input.first().json.Remote || "";
const easyApply = $input.first().json['Easy Apply'] || "";

// 3. Inject Anti-Spam into the Keyword string (UPDATED with AI evaluation spam)
const spamBlocker = "NOT Turing NOT Canonical NOT BairesDev NOT Crossover NOT Revature NOT SynergisticIT NOT Outlier NOT \"Scale AI\" NOT DataAnnotation NOT Mercor NOT Alignerr";
const keyword = baseKeyword ? `${baseKeyword} ${spamBlocker}` : spamBlocker;

url += `&keywords=${encodeURIComponent(keyword)}`;

if (location != "") {
  url += `&location=${encodeURIComponent(location)}`;
}

// 4. Case-Insensitive Experience Level Mapping (1=Intern, 2=Entry, 3=Associate)
if (experienceLevel !== "") {
  const transformedExperiences = experienceLevel
    .split(",")
    .map((exp) => {
      const cleanExp = exp.trim().toLowerCase();
      if (cleanExp === "internship") return "1";
      if (cleanExp === "entry level") return "2";
      if (cleanExp === "associate") return "3";
      return "";
    })
    .filter(Boolean);

  if (transformedExperiences.length > 0) {
    url += `&f_E=${transformedExperiences.join(",")}`;
  }
}

// 5. Case-Insensitive Remote Mapping
if (remote != "") {
  const transformedRemote = remote
    .split(",")
    .map((e) => {
      const cleanRemote = e.trim().toLowerCase();
      if (cleanRemote === "remote") return "2";
      if (cleanRemote === "hybrid") return "3";
      if (cleanRemote === "on-site") return "1";
      return "";
    })
    .filter(Boolean);

  if (transformedRemote.length > 0) {
    url += `&f_WT=${transformedRemote.join(",")}`;
  }
}

// 6. Easy Apply Mapping
if (easyApply === true || easyApply === "true" || String(easyApply).toLowerCase() === "yes") {
  url += "&f_EA=true";
}

return { url };

