// 1. Initialize n8n's "Memory" to track seen jobs
const staticData = $getWorkflowStaticData('global');
staticData.seenJobs = staticData.seenJobs ||[];

const description = $input.item.json.Description || "";
const title = $input.item.json.Title || "";
const company = $input.item.json.Company || "";

// 2. Create the Composite Key (e.g., "google - data engineer")
const compositeKey = `${company} - ${title}`.toLowerCase().trim();
const textToCheck = (title + " " + company + " " + description).toLowerCase();

let passesFilter = true;
let reason = "Clean"; 

// ==========================================
// FILTER 1: Deduplication Check (Fastest)
// ==========================================
if (staticData.seenJobs.includes(compositeKey)) {
    passesFilter = false;
    reason = `Rejected: Duplicate Role (${compositeKey})`;
} else {
    // If it's a new job, save it to the memory so we don't process it again
    staticData.seenJobs.push(compositeKey);
}

// ==========================================
// FILTER 2: Safe Phrases & Bad Keywords
// ==========================================
// Only run the heavy text scanning if it's NOT a duplicate
if (passesFilter) {
    // Safe phrases: Bypass the C2C filter if the job explicitly states it is W2
    const safePhrases =["no c2c", "not c2c", "w2 only", "w-2 only", "w2 candidates only", "no corp to corp", "no corp-to-corp"];
    let hasSafePhrase = safePhrases.some(phrase => textToCheck.includes(phrase));

    // Strict Clearance & Citizenship
    const badKeywords =[
      "u.s. citizen", "us citizen", "u.s. citizens only", "green card", 
      "permanent resident only", "u.s. person", "security clearance", 
      "active clearance", "top secret", "ts/sci", "export control", 
      "department of defense", "us government", 
      "defense contractor", "aerospace & defense", 
      "raytheon", "lockheed martin", "northrop grumman"
    ];
    const strictClearanceKeywords =["secret", " sci ", " dod "];

    // Contract constraints (1099/C2C)
    const contractKeywords =["independent contractor", "freelance", "corp-to-corp", "corp to corp", "self-employed"];
    const strictContractKeywords = ["1099", "c2c"];

    // Check standard clearance/citizenship phrases
    for (const kw of badKeywords) {
      if (textToCheck.includes(kw)) {
        passesFilter = false;
        reason = `Rejected: Found '${kw}'`;
        break;
      }
    }

    if (passesFilter) {
      for (const kw of strictClearanceKeywords) {
        const regex = new RegExp(`\\b${kw}\\b`, 'i');
        if (regex.test(textToCheck)) {
          passesFilter = false;
          reason = `Rejected: Found strict clearance word '${kw}'`;
          break;
        }
      }
    }

    // Check 1099/C2C ONLY IF it doesn't have a "No C2C" safe phrase
    if (passesFilter && !hasSafePhrase) {
      for (const kw of contractKeywords) {
        if (textToCheck.includes(kw)) {
          passesFilter = false;
          reason = `Rejected: Found contract word '${kw}'`;
          break;
        }
      }

      if (passesFilter) {
        for (const kw of strictContractKeywords) {
          const regex = new RegExp(`\\b${kw}\\b`, 'i');
          if (regex.test(textToCheck)) {
            passesFilter = false;
            reason = `Rejected: Found strict contract word '${kw}'`;
            break;
          }
        }
      }
    }
}

// Return the final decision
return {
  json: {
    ...$input.item.json,
    passes_filter: passesFilter,
    reject_reason: reason
  }
};

